 1→//! CipherBox Rust Crypto Module
 2→//!
 3→//! Mirrors the @cipherbox/crypto TypeScript module for cross-language compatibility.
 4→//! All operations produce byte-identical output to the TypeScript implementation.
 5→
 6→pub mod aes;
 7→pub mod aes_ctr;
 8→pub mod ecies;
 9→pub mod ed25519;
10→pub mod folder;
11→pub mod hkdf;
12→pub mod ipns;
13→pub mod utils;
14→
15→#[cfg(test)]
16→mod tests;
17→
18→// Re-export primary functions for convenience
19→pub use aes::{decrypt_aes_gcm, encrypt_aes_gcm, seal_aes_gcm, unseal_aes_gcm};
20→pub use ecies::{unwrap_key, wrap_key};
21→pub use ed25519::{generate_ed25519_keypair, get_public_key, sign_ed25519, verify_ed25519};
22→pub use folder::{decrypt_folder_metadata, encrypt_folder_metadata, FolderMetadata};
23→pub use ipns::{create_ipns_record, derive_ipns_name, marshal_ipns_record, IpnsRecord};
24→pub use utils::{clear_bytes, generate_file_key, generate_iv, generate_random_bytes};
