  1→/**
  2→ * Generate cross-language test vectors for Rust crypto module verification.
  3→ *
  4→ * Uses @cipherbox/crypto TypeScript module to produce deterministic test vectors
  5→ * that the Rust tests will verify against.
  6→ *
  7→ * Usage: node generate-test-vectors.mjs
  8→ * Requires: pnpm build in packages/crypto first
  9→ */
 10→
 11→import {
 12→  encryptAesGcm,
 13→  decryptAesGcm,
 14→  sealAesGcm,
 15→  unsealAesGcm,
 16→  wrapKey,
 17→  unwrapKey,
 18→  signEd25519,
 19→  verifyEd25519,
 20→  createIpnsRecord,
 21→  marshalIpnsRecord,
 22→  deriveIpnsName,
 23→  hexToBytes,
 24→  bytesToHex,
 25→} from '../../../packages/crypto/dist/index.mjs';
 26→
 27→import { getPublicKey } from '../../../packages/crypto/node_modules/@noble/secp256k1/index.js';
 28→import * as ed from '../../../packages/crypto/node_modules/@noble/ed25519/index.js';
 29→
 30→function toHex(bytes) {
 31→  return bytesToHex(bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes));
 32→}
 33→
 34→async function main() {
 35→  console.log('=== CipherBox Cross-Language Test Vectors ===\n');
 36→
 37→  // ---- Fixed keys for deterministic tests ----
 38→
 39→  // AES key (32 bytes)
 40→  const aesKey = hexToBytes('0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef');
 41→  // AES IV (12 bytes)
 42→  const aesIv = hexToBytes('aabbccddeeff00112233aabb');
 43→  // Plaintext
 44→  const plaintext = new TextEncoder().encode('Hello, CipherBox!');
 45→
 46→  // 1. AES-256-GCM with fixed key and IV
 47→  console.log('--- AES-256-GCM Test Vector ---');
 48→  const ciphertext = await encryptAesGcm(plaintext, aesKey, aesIv);
 49→  console.log(`AES_KEY: "${toHex(aesKey)}"`);
 50→  console.log(`AES_IV: "${toHex(aesIv)}"`);
 51→  console.log(`PLAINTEXT: "Hello, CipherBox!"`);
 52→  console.log(`PLAINTEXT_HEX: "${toHex(plaintext)}"`);
 53→  console.log(`CIPHERTEXT_WITH_TAG: "${toHex(ciphertext)}"`);
 54→  console.log(`CIPHERTEXT_LEN: ${ciphertext.length}`);
 55→  console.log();
 56→
 57→  // Verify round-trip
 58→  const decrypted = await decryptAesGcm(ciphertext, aesKey, aesIv);
 59→  console.log(`DECRYPTED: "${new TextDecoder().decode(decrypted)}"`);
 60→  console.log();
 61→
 62→  // 2. AES seal (uses random IV, so we produce a sealed blob and verify the format)
 63→  console.log('--- AES Seal Format Test Vector ---');
 64→  const sealed = await sealAesGcm(plaintext, aesKey);
 65→  console.log(`SEALED_HEX: "${toHex(sealed)}"`);
 66→  console.log(`SEALED_LEN: ${sealed.length}`);
 67→  // Extract IV from sealed to verify unsealing works
 68→  const sealedIv = sealed.slice(0, 12);
 69→  console.log(`SEALED_IV: "${toHex(sealedIv)}"`);
 70→  const unsealed = await unsealAesGcm(sealed, aesKey);
 71→  console.log(`UNSEALED: "${new TextDecoder().decode(unsealed)}"`);
 72→  console.log();
 73→
 74→  // 3. Ed25519 with fixed private key
 75→  console.log('--- Ed25519 Test Vector ---');
 76→  const ed25519PrivateKey = hexToBytes(
 77→    '9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60'
 78→  );
 79→  const ed25519PublicKey = ed.getPublicKey(ed25519PrivateKey);
 80→  console.log(`ED25519_PRIVATE_KEY: "${toHex(ed25519PrivateKey)}"`);
 81→  console.log(`ED25519_PUBLIC_KEY: "${toHex(ed25519PublicKey)}"`);
 82→
 83→  const message = new TextEncoder().encode('Hello, CipherBox!');
 84→  const signature = await signEd25519(message, ed25519PrivateKey);
 85→  console.log(`ED25519_MESSAGE: "Hello, CipherBox!"`);
 86→  console.log(`ED25519_SIGNATURE: "${toHex(signature)}"`);
 87→  console.log(`ED25519_SIGNATURE_LEN: ${signature.length}`);
 88→
 89→  const valid = await verifyEd25519(signature, message, ed25519PublicKey);
 90→  console.log(`ED25519_VERIFY: ${valid}`);
 91→  console.log();
 92→
 93→  // 4. ECIES with fixed secp256k1 keypair
 94→  console.log('--- ECIES Test Vector ---');
