49→/// Timeout for network I/O in filesystem callbacks to prevent blocking the mount thread.
50→#[cfg(any(feature = "fuse", feature = "winfsp"))]
51→const NETWORK_TIMEOUT: Duration = Duration::from_secs(10);
52→
53→/// Run an async future with a timeout on the tokio runtime.
54→/// Prevents filesystem thread hangs from indefinite network I/O.
55→#[cfg(any(feature = "fuse", feature = "winfsp"))]
56→fn block_with_timeout<F, T>(rt: &tokio::runtime::Handle, fut: F) -> Result<T, String>
57→where
58→    F: std::future::Future<Output = Result<T, String>>,
59→{
60→    rt.block_on(async {
61→        match tokio::time::timeout(NETWORK_TIMEOUT, fut).await {
62→            Ok(result) => result,
63→            Err(_) => Err("Operation timed out".to_string()),
64→        }
65→    })
66→}
