704→fn ipns_record_signature_v2_is_deterministic_for_same_cbor() {
705→    // Since the CBOR data includes a timestamp, the signature will differ
706→    // between calls. But for the SAME CBOR data, the signature must be deterministic.
707→    let private_key = hex::decode(ED25519_TEST_PRIVATE_KEY).unwrap();
708→    let pk: [u8; 32] = private_key.clone().try_into().unwrap();
