714→    let mut data_to_sign = Vec::new();
715→    data_to_sign.extend_from_slice(prefix);
716→    data_to_sign.extend_from_slice(&record.data);
717→
718→    let sig = ed25519::sign_ed25519(&data_to_sign, &private_key).unwrap();
