const crypto = require('crypto');

// AES-256-CTR test vector with same key as GCM tests
const key = Buffer.from('0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef', 'hex');
// 16-byte IV for CTR (Ctr64BE: first 8 bytes nonce, last 8 bytes counter starting at 0)
const iv = Buffer.from('aabbccddeeff001100000000000000000', 'hex');

// Actually let's use a proper 16-byte IV
const iv2 = Buffer.from('aabbccddeeff00110000000000000000', 'hex');
const plaintext = Buffer.from('Hello, CipherBox!');

const cipher = crypto.createCipheriv('aes-256-ctr', key, iv2);
const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
console.log('key:', key.toString('hex'));
console.log('iv:', iv2.toString('hex'));
console.log('plaintext_hex:', plaintext.toString('hex'));
console.log('ciphertext_hex:', ciphertext.toString('hex'));
"

